package org.sleepwell.app;

import android.app.*;import android.content.*;import android.os.*;import android.view.View;import androidx.activity.ComponentActivity;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import org.junit.Test;import java.io.File;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;

/** Private configuration and actual generated decoder proof only. No CameraX/AlarmActivity output. */
public final class BarcodeCodeFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);volatile Activity current;
    static final class Access implements QrCameraAccess.Port {QrCameraAccess.Status state=QrCameraAccess.Status.NEEDED;int requests;public QrCameraAccess.Status status(Activity a){return state;}public void request(Activity a){requests++;}}
    static final class Camera implements QrCamera.Port {final View preview;String format=MorningBarcode.QR;QrScanSession.Listener listener;Camera(ComponentActivity a){preview=new View(a);}public void format(String format){this.format=format;}public View preview(){return preview;}public void start(QrScanSession.Listener listener){this.listener=listener;}public void close(){}}
    UiObject2 object(String description)throws Exception{UiObject2 view=d.findObject(By.desc(description));if(view==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description(description));view=d.wait(Until.findObject(By.desc(description)),5000);}assertNotNull(description,view);return view;}
    void click(String label)throws Exception{UiObject2 view=d.findObject(By.text(label));if(view==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(label));view=d.wait(Until.findObject(By.text(label)),5000);}assertNotNull(label,view);view.click();d.waitForIdle();}
    void shown(String text){assertTrue(text,d.wait(Until.hasObject(By.text(text)),6000));}
    void recreate(String text)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(current.getClass().getName(),null,false);try{i.runOnMainSync(current::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}shown(text);}
    void capture(String name)throws Exception{i.waitForIdleSync();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(d.takeScreenshot(new File(folder,"barcode-code-"+name+".png")));}
    String digest()throws Exception{BitMatrix matrix=new MultiFormatWriter().encode("MORNING-42",BarcodeFormat.CODE_128,640,240,Map.of(EncodeHintType.MARGIN,20));byte[] luma=new byte[matrix.getWidth()*matrix.getHeight()];for(int y=0;y<matrix.getHeight();y++)for(int x=0;x<matrix.getWidth();x++)luma[y*matrix.getWidth()+x]=(byte)(matrix.get(x,y)?0:255);return new QrDecoder("CODE_128").digest(luma,matrix.getWidth(),matrix.getHeight());}
    @Test public void explicitBarcodeModePermissionCancelCaptureRecreationAndReopenRemainPrivate()throws Exception{String name="barcode-flow-"+UUID.randomUUID();Records.Factory oldRecords=Records.factory;AlarmScheduling.Port oldScheduling=AlarmScheduling.port;QrCameraAccess.Port oldAccess=QrCameraAccess.port;QrCamera.Factory oldCamera=QrCamera.factory;Map<String,?> original=new HashMap<>(Prefs.of(c).getAll());Access access=new Access();List<Camera> cameras=new CopyOnWriteArrayList<>();List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue(a instanceof AlarmEditorActivity||a instanceof QrCodeActivity);assertFalse(a.getIntent().getBooleanExtra("challenge",false));owned.add(a);}public void onActivityResumed(Activity a){current=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        try{Records.factory=context->new Store(context,name);AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context x){return true;}public void schedule(Context x,Alarm alarm){assertFalse(alarm.enabled);}};QrCameraAccess.port=access;QrCamera.factory=a->{Camera camera=new Camera(a);cameras.add(camera);return camera;};Alarm alarm=new Alarm(1);alarm.enabled=false;try(Store store=new Store(c,name)){store.save(alarm);}Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}shown("Edit alarm");click("Challenges");object("Configure QR code").click();shown("Add a morning code");click("Barcode");shown("EAN-13");capture("mode");click("Barcode format");click("Code 128");object("Barcode location name").setText("Kitchen");click("Allow camera");assertEquals(1,access.requests);i.runOnMainSync(()->((QrCodeActivity)current).onRequestPermissionsResult(QrCameraAccess.REQUEST,new String[]{android.Manifest.permission.CAMERA},new int[]{android.content.pm.PackageManager.PERMISSION_DENIED}));assertTrue(object("QR scan error").getText().contains("not allowed"));assertTrue(cameras.isEmpty());object("Back").click();shown("Challenges");try(Store store=new Store(c,name)){assertFalse(store.alarm(1).json().has("routine"));}
        object("Configure QR code").click();shown("Add a morning code");click("Barcode");click("Barcode format");click("Code 128");object("Barcode location name").setText("Kitchen");access.state=QrCameraAccess.Status.READY;recreate("Add a morning code");shown("Code 128");click("Scan code");assertTrue(d.wait(Until.hasObject(By.desc("Barcode camera preview")),5000));assertFalse(cameras.isEmpty());Camera first=cameras.get(cameras.size()-1);assertEquals("CODE_128",first.format);String hash=digest();assertNotNull(hash);i.runOnMainSync(()->first.listener.captured(hash));shown("Code captured");capture("captured");click("QR code");assertFalse(d.hasObject(By.text("Code captured")));click("Save code");assertFalse(object("QR scan error").getText().isBlank());click("Barcode");click("Barcode format");click("Code 128");click("Scan code");Camera second=cameras.get(cameras.size()-1);assertNotSame(first,second);i.runOnMainSync(()->first.listener.captured(hash));assertFalse(d.hasObject(By.text("Code captured")));i.runOnMainSync(()->second.listener.captured(hash));shown("Code captured");recreate("Add a morning code");shown("Code 128");assertEquals("Kitchen",object("Barcode location name").getText());capture("recreated");click("Save code");shown("Challenges");capture("routine");click("Save routine");click("Save alarm");try(Store store=new Store(c,name)){MorningCode saved=store.alarm(1).challenges().tasks.get(1).code;assertEquals("CODE_128",saved.format);assertEquals(hash,saved.hash);assertEquals("Kitchen",saved.label);Backup.validate(store.backup());assertFalse(store.backup().toString().contains("MORNING-42"));}
        // Reopen the real task editor from saved state without enabling or scheduling an alarm.
        Alarm saved;try(Store store=new Store(c,name)){saved=store.alarm(1);}monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",saved.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}shown("Edit alarm");click("Challenges");object("Edit task 2 QR code").click();shown("Add a morning code");shown("Code 128");shown("Code captured");access.state=QrCameraAccess.Status.UNSUPPORTED;recreate("Add a morning code");shown("No supported camera is available.");capture("reopened");assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertEquals(original,Prefs.of(c).getAll());
        }finally{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(25);assertTrue(owned.stream().allMatch(Activity::isDestroyed));app.unregisterActivityLifecycleCallbacks(lifecycle);Records.factory=oldRecords;AlarmScheduling.port=oldScheduling;QrCameraAccess.port=oldAccess;QrCamera.factory=oldCamera;c.deleteDatabase(name);}}
}
